-- JIGME TENZIN ePORTFOLIO - SAFE INSTALL / MIGRATION
-- This script is designed for an existing project too.
-- RLS stays ENABLED. Run the whole file in a NEW SQL Editor query.

create table if not exists portfolio_profile(id bigint generated by default as identity primary key,name text not null,intro text,profile_image text,cv_url text,contact_email text,contact_phone text,updated_at timestamptz default now());
create table if not exists portfolio_skills(id bigint generated by default as identity primary key,name text not null,description text,level integer default 75 check(level between 0 and 100),icon text default '✨',color text default '#22d3ee',image_url text,video_url text,gallery text,display_order integer default 0);
create table if not exists portfolio_education(id bigint generated by default as identity primary key,period text not null,title text not null,institution text,description text,image_url text,video_url text,certificate_url text,gallery text,display_order integer default 0);
create table if not exists portfolio_about(id bigint generated by default as identity primary key,content text not null,content_before text,content_middle text,content_after text,image_url text,video_url text,gallery text,updated_at timestamptz default now());
create table if not exists portfolio_projects(id bigint generated by default as identity primary key,title text not null,description text,tech text,technologies text,image_url text,project_url text,github_url text,icon text default '✦',video_url text,gallery text,display_order integer default 0,created_at timestamptz default now());
create table if not exists portfolio_socials(id bigint generated by default as identity primary key,name text not null,url text not null,icon text default '↗',display_order integer default 0);
create table if not exists portfolio_messages(id bigint generated by default as identity primary key,name text not null,email text not null,message text not null,created_at timestamptz default now(),is_read boolean default false);
create table if not exists portfolio_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz default now());

alter table portfolio_about add column if not exists content_before text;
alter table portfolio_about add column if not exists content_middle text;
alter table portfolio_about add column if not exists content_after text;
alter table portfolio_about add column if not exists image_url text;
alter table portfolio_about add column if not exists video_url text;
alter table portfolio_about add column if not exists gallery text;

-- Migrate older project-table versions safely.
alter table portfolio_profile add column if not exists profile_image text;
alter table portfolio_profile add column if not exists cv_url text;
alter table portfolio_profile add column if not exists contact_email text;
alter table portfolio_profile add column if not exists contact_phone text;
alter table portfolio_skills add column if not exists color text default '#22d3ee';
alter table portfolio_projects add column if not exists tech text;
alter table portfolio_projects add column if not exists technologies text;
alter table portfolio_projects add column if not exists image_url text;
alter table portfolio_projects add column if not exists project_url text;
alter table portfolio_projects add column if not exists github_url text;
alter table portfolio_projects add column if not exists icon text default '✦';
alter table portfolio_projects add column if not exists display_order integer default 0;
alter table portfolio_projects add column if not exists created_at timestamptz default now();

alter table portfolio_skills add column if not exists image_url text;
alter table portfolio_skills add column if not exists video_url text;
alter table portfolio_skills add column if not exists gallery text;
alter table portfolio_education add column if not exists image_url text;
alter table portfolio_education add column if not exists video_url text;
alter table portfolio_education add column if not exists certificate_url text;
alter table portfolio_education add column if not exists gallery text;
alter table portfolio_projects add column if not exists video_url text;
alter table portfolio_projects add column if not exists gallery text;


alter table portfolio_profile enable row level security;
alter table portfolio_skills enable row level security;
alter table portfolio_education enable row level security;
alter table portfolio_about enable row level security;
alter table portfolio_projects enable row level security;
alter table portfolio_socials enable row level security;
alter table portfolio_messages enable row level security;
alter table portfolio_admins enable row level security;

-- Public read policies for portfolio content.
drop policy if exists "portfolio profile public read" on portfolio_profile;
create policy "portfolio profile public read" on portfolio_profile for select to anon,authenticated using(true);
drop policy if exists "portfolio skills public read" on portfolio_skills;
create policy "portfolio skills public read" on portfolio_skills for select to anon,authenticated using(true);
drop policy if exists "portfolio education public read" on portfolio_education;
create policy "portfolio education public read" on portfolio_education for select to anon,authenticated using(true);
drop policy if exists "portfolio about public read" on portfolio_about;
create policy "portfolio about public read" on portfolio_about for select to anon,authenticated using(true);
drop policy if exists "portfolio projects public read" on portfolio_projects;
create policy "portfolio projects public read" on portfolio_projects for select to anon,authenticated using(true);
drop policy if exists "portfolio socials public read" on portfolio_socials;
create policy "portfolio socials public read" on portfolio_socials for select to anon,authenticated using(true);

-- Contact form: anyone can submit, nobody can read through the public anon key.
drop policy if exists "portfolio messages public insert" on portfolio_messages;
create policy "portfolio messages public insert" on portfolio_messages for insert to anon,authenticated with check(true);
drop policy if exists "portfolio messages admin read" on portfolio_messages;
create policy "portfolio messages admin read" on portfolio_messages for select to authenticated using(exists(select 1 from portfolio_admins a where a.user_id=auth.uid()));

-- Admin table: users can see only their own admin record.
drop policy if exists "portfolio admins self read" on portfolio_admins;
create policy "portfolio admins self read" on portfolio_admins for select to authenticated using(user_id=auth.uid());

-- Authenticated admins can edit portfolio content.
drop policy if exists "portfolio profile admin write" on portfolio_profile;
create policy "portfolio profile admin write" on portfolio_profile for all to authenticated using(exists(select 1 from portfolio_admins a where a.user_id=auth.uid())) with check(exists(select 1 from portfolio_admins a where a.user_id=auth.uid()));
drop policy if exists "portfolio skills admin write" on portfolio_skills;
create policy "portfolio skills admin write" on portfolio_skills for all to authenticated using(exists(select 1 from portfolio_admins a where a.user_id=auth.uid())) with check(exists(select 1 from portfolio_admins a where a.user_id=auth.uid()));
drop policy if exists "portfolio education admin write" on portfolio_education;
create policy "portfolio education admin write" on portfolio_education for all to authenticated using(exists(select 1 from portfolio_admins a where a.user_id=auth.uid())) with check(exists(select 1 from portfolio_admins a where a.user_id=auth.uid()));
drop policy if exists "portfolio about admin write" on portfolio_about;
create policy "portfolio about admin write" on portfolio_about for all to authenticated using(exists(select 1 from portfolio_admins a where a.user_id=auth.uid())) with check(exists(select 1 from portfolio_admins a where a.user_id=auth.uid()));
drop policy if exists "portfolio projects admin write" on portfolio_projects;
create policy "portfolio projects admin write" on portfolio_projects for all to authenticated using(exists(select 1 from portfolio_admins a where a.user_id=auth.uid())) with check(exists(select 1 from portfolio_admins a where a.user_id=auth.uid()));
drop policy if exists "portfolio socials admin write" on portfolio_socials;
create policy "portfolio socials admin write" on portfolio_socials for all to authenticated using(exists(select 1 from portfolio_admins a where a.user_id=auth.uid())) with check(exists(select 1 from portfolio_admins a where a.user_id=auth.uid()));
drop policy if exists "portfolio messages admin update" on portfolio_messages;
create policy "portfolio messages admin update" on portfolio_messages for update to authenticated using(exists(select 1 from portfolio_admins a where a.user_id=auth.uid())) with check(exists(select 1 from portfolio_admins a where a.user_id=auth.uid()));
drop policy if exists "portfolio messages admin delete" on portfolio_messages;
create policy "portfolio messages admin delete" on portfolio_messages for delete to authenticated using(exists(select 1 from portfolio_admins a where a.user_id=auth.uid()));

