-- ================= IMAGE UPLOADS (Storage) =================
-- One public bucket holds every uploaded image (profile photo, skill icons,
-- project images, social icons). Public can only READ; only a signed-in
-- admin (present in portfolio_admins) can upload/replace/delete.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('portfolio-media','portfolio-media', true, 52428800, ARRAY['image/*','video/*','application/pdf'])
  on conflict (id) do update set public = true, file_size_limit = 52428800, allowed_mime_types = ARRAY['image/*','video/*','application/pdf'];

drop policy if exists "portfolio media public read" on storage.objects;
create policy "portfolio media public read" on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'portfolio-media');

drop policy if exists "portfolio media admin insert" on storage.objects;
create policy "portfolio media admin insert" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'portfolio-media' and exists(select 1 from portfolio_admins a where a.user_id = auth.uid()));

drop policy if exists "portfolio media admin update" on storage.objects;
create policy "portfolio media admin update" on storage.objects
  for update to authenticated
  using (bucket_id = 'portfolio-media' and exists(select 1 from portfolio_admins a where a.user_id = auth.uid()))
  with check (bucket_id = 'portfolio-media' and exists(select 1 from portfolio_admins a where a.user_id = auth.uid()));

drop policy if exists "portfolio media admin delete" on storage.objects;
create policy "portfolio media admin delete" on storage.objects
  for delete to authenticated
  using (bucket_id = 'portfolio-media' and exists(select 1 from portfolio_admins a where a.user_id = auth.uid()));

-- ADMIN SETUP:
-- 1) Create your admin user in Supabase Authentication > Users.
-- 2) Copy that user's UUID.
-- 3) Run: insert into portfolio_admins(user_id) values('YOUR-USER-UUID');
-- 4) If "Add/Edit/Delete" ever silently fails for ANY section (Skills,
--    Social Links, etc.), it is almost always this step: that logged-in
--    user's UUID is missing from portfolio_admins. Re-run step 3.
